--
-- Table structure for table `show_roles`
--

DROP TABLE IF EXISTS `show_roles`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `show_roles` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `role` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `character_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `character_photo` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `show_id` bigint unsigned NOT NULL,
  `people_id` bigint unsigned NOT NULL,
  PRIMARY KEY (`id`),
  KEY `fk_roles_show` (`show_id`),
  KEY `fk_roles_people` (`people_id`),
  CONSTRAINT `fk_roles_people` FOREIGN KEY (`people_id`) REFERENCES `people` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_roles_show` FOREIGN KEY (`show_id`) REFERENCES `shows` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=2499 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

